+      double dateGroup = stmt->AsInt64(12);
+      JS_DefineProperty(cx, obj, "dateGroup", dateGroup, JSPROP_ENUMERATE);
+    }
+    Rooted<Value> message(cx, ObjectValue(*obj));
+    JS_DefineElement(cx, arr, count++, message, JSPROP_ENUMERATE);
+  }
